     1→const axios = require('axios');
     2→
     3→const POKEAPI_BASE_URL = 'https://pokeapi.co/api/v2';
     4→const POKEMON_LIST_CACHE_TTL = 1000 * 60 * 60; // 1 hour
     5→
     6→// In-memory cache for Pokemon list
     7→let pokemonListCache = null;
     8→let cacheTimestamp = null;
     9→
    10→/**
    11→ * Fetch all Pokemon names from PokeAPI
    12→ * Uses caching to avoid repeated API calls
    13→ */
    14→async function getAllPokemonNames() {
    15→  const now = Date.now();
    16→
    17→  // Return cached data if still valid
    18→  if (pokemonListCache && cacheTimestamp && (now - cacheTimestamp) < POKEMON_LIST_CACHE_TTL) {
    19→    return pokemonListCache;
    20→  }
    21→
    22→  try {
    23→    const response = await axios.get(`${POKEAPI_BASE_URL}/pokemon?limit=10000`, {
    24→      timeout: 10000 // 10 second timeout
    25→    });
    26→
    27→    pokemonListCache = response.data.results.map(pokemon => ({
    28→      name: pokemon.name,
    29→      url: pokemon.url
    30→    }));
    31→    cacheTimestamp = now;
    32→
    33→    return pokemonListCache;
    34→  } catch (error) {
    35→    // If cache exists but is expired, return it anyway on error
    36→    if (pokemonListCache) {
    37→      console.error('PokeAPI fetch failed, returning stale cache:', error.message);
    38→      return pokemonListCache;
    39→    }
    40→    throw new Error(`Failed to fetch Pokemon list: ${error.message}`);
    41→  }
    42→}
    43→
    44→/**
    45→ * Search Pokemon by partial name (case-insensitive)
    46→ * @param {string} query - Search query (full or partial name)
    47→ * @returns {Promise<Array>} - Array of matching Pokemon names
    48→ */
    49→async function searchPokemonByPartialName(query) {
    50→  if (!query || typeof query !== 'string') {
    51→    return [];
    52→  }
    53→
    54→  const allPokemon = await getAllPokemonNames();
    55→  const normalizedQuery = query.toLowerCase().trim();
    56→
    57→  if (normalizedQuery === '') {
    58→    return [];
    59→  }
    60→
    61→  return allPokemon.filter(pokemon =>
    62→    pokemon.name.toLowerCase().includes(normalizedQuery)
    63→  );
    64→}
    65→
    66→/**
    67→ * Get detailed Pokemon data by name
    68→ * @param {string} name - Pokemon name
    69→ * @returns {Promise<Object>} - Pokemon data including types
    70→ */
    71→async function getPokemonByName(name) {
    72→  if (!name || typeof name !== 'string') {
    73→    throw new Error('Invalid Pokemon name');
    74→  }
    75→
    76→  try {
    77→    const response = await axios.get(`${POKEAPI_BASE_URL}/pokemon/${name.toLowerCase()}`, {
    78→      timeout: 10000 // 10 second timeout
    79→    });
    80→
    81→    return {
    82→      name: response.data.name,
    83→      types: response.data.types.map(typeInfo => typeInfo.type.name),
    84→      id: response.data.id,
    85→      height: response.data.height,
    86→      weight: response.data.weight
    87→    };
    88→  } catch (error) {
    89→    if (error.response && error.response.status === 404) {
    90→      throw new Error(`Pokemon '${name}' not found`);
    91→    }
    92→    throw new Error(`Failed to fetch Pokemon details: ${error.message}`);
    93→  }
    94→}
    95→
    96→module.exports = {
    97→  getAllPokemonNames,
    98→  searchPokemonByPartialName,
    99→  getPokemonByName
   100→};
   101→

